import { _decorator, Component, Node } from 'cc';
import { HallEvents } from './HallEvents';
import { Bus } from '../Engine/Bus';
const { ccclass, property } = _decorator;

@ccclass('HallScene')
export class HallScene extends Component {

    private _gameSeconds = 0;
    private _secondsPerMonth = 60;
    private _bus: Bus = null;

    // 在 update 或 FixedTick 的 onTick 回调里
    private _onHallTick(dt: number): void {
        this._gameSeconds += dt;
        if (this._gameSeconds >= this._secondsPerMonth) {
            this._gameSeconds -= this._secondsPerMonth;
            this._bus.emit(HallEvents.MONTH_PASSED, this._gameSeconds);
        }
    }
}


